const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sample = {story:'领导刚加了一个 B 方案，要求明天完成。但我手里的 A 项目明天下午也要交。我担心直接说做不完，会让领导觉得我能力不行。',existing:'A 项目 · 明天下午交付',added:'B 方案 · 明天完成',constraint:'两项合计还需 2 天，目前只剩 1 天',goal:'请领导确认优先级，并调整时间或交付范围',preference:'先说结论，再讲关键事实'};
let state;
const doubaoAvatar = '<img src="data:image/png;base64," alt="豆包头像" width="42" height="42">';
let pendingChat = null;
const isReplyPending = () => pendingChat?.messages === state.messages;
const labels = ['说说情况','确认要点','准备表达','沟通对练','回看反馈','带走提纲'];

// AI connection and request plumbing retained from the original product.
const connectionKey='workplace-ai-connection-v1';
const providers={openai:{label:'OpenAI / GPT-6 Luna',baseUrl:'https://api.openai.com/v1',model:'gpt-6-luna'},deepseek:{label:'DeepSeek',baseUrl:'https://api.deepseek.com',model:'deepseek-flash'},compatible:{label:'其他兼容服务',baseUrl:'',model:''}};
const defaultConnection={provider:'deepseek',baseUrl:'https://api.deepseek.com',model:'deepseek-flash'};
let connection={mode:'default',provider:defaultConnection.provider,apiKey:'',baseUrl:defaultConnection.baseUrl,model:defaultConnection.model};
let connectionStatus={configured:false,provider:'DeepSeek',model:defaultConnection.model};
try{const saved=JSON.parse(sessionStorage.getItem(connectionKey)||'null');if(saved?.mode==='custom'||saved?.mode==='disabled')connection={mode:saved.mode,provider:saved.provider||'deepseek',apiKey:String(saved.apiKey||'').trim(),baseUrl:saved.baseUrl||'',model:saved.model||''};}catch{}
let busy=false,controller=null;
function activeClientConfig(){return connection.mode==='default'?null:{useDefault:false,provider:connection.provider,apiKey:connection.apiKey,baseUrl:connection.baseUrl,model:connection.model};}
function aiPayload(action,extra={}){const fields={existing:state.existing||'',added:state.added||'',constraint:state.constraint||'',original:state.original||'',known:state.known||'',goal:state.goal||''};return {action,scene:state.scene,story:state.story||'',fields,questions:selectedQuestions(),preference:state.preference||'',tone:state.tone||'自然',transcript:state.messages||[],clientConfig:activeClientConfig(),...extra};}
async function aiApi(action,extra={}){const res=await fetch('/api/ai',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(aiPayload(action,extra)),signal:controller?.signal});let body;try{body=await res.json();}catch{throw new Error('服务器没有返回有效内容，请稍后重试。');}if(!res.ok)throw new Error(body.error||'AI 请求未成功，请重试。');return body.data;}
async function performAI(message,fn){if(busy)return false;busy=true;controller=new AbortController();const app=$('#app');app.inert=true;app.setAttribute('aria-busy','true');toast(message);try{await fn();return true;}catch(e){if(e.name!=='AbortError')toast(e.message||'AI 请求失败，请重试。');return false;}finally{busy=false;controller=null;app.inert=false;app.removeAttribute('aria-busy');if(state.step===2)render();}}
function saveConnection(){try{if(connection.mode==='default')sessionStorage.removeItem(connectionKey);else sessionStorage.setItem(connectionKey,JSON.stringify(connection));}catch{}}
function updateConnectionButton(){const label=$('#connection-label'),dot=$('.connection-dot');if(!label)return;label.textContent=connection.mode==='custom'?'AI 已连接':connection.mode==='disabled'?'AI 未连接':connectionStatus.configured?'AI 已连接':'AI 未连接';if(dot)dot.classList.toggle('ready',connection.mode==='custom'||(connection.mode==='default'&&connectionStatus.configured));}
async function loadConnectionStatus(){try{const r=await fetch('/api/status');const b=await r.json();connectionStatus={...connectionStatus,...b};}catch{}updateConnectionButton();}
function connectionModal(){const custom=connection.mode==='custom',disabled=connection.mode==='disabled',chosen=providers[connection.provider]||providers.compatible;showModal(`<div class="modal-heading"><div><h2>连接 AI</h2><p class="modal-sub">默认使用 DeepSeek 官方服务，也可以停用默认配置并连接自己的模型。</p></div><button data-close aria-label="关闭">×</button></div><div class="connection-current ${connectionStatus.configured?'ready':'not-ready'}"><span class="connection-dot"></span><div><strong>${custom?'当前使用我的 Key':disabled?'已停用产品默认配置':connectionStatus.configured?'当前使用产品默认配置':'默认配置尚未就绪'}</strong><small>${esc(custom?`${chosen.label} · ${connection.baseUrl||'请填写服务地址'} · ${connection.model||'请填写模型'}`:`${connectionStatus.provider} · ${connectionStatus.model}`)}</small></div><span class="connection-badge">${custom||disabled?'本次会话':'服务端'}</span></div><div class="connection-form"><label>我的模型服务<select id="custom-provider">${Object.entries(providers).map(([key,p])=>`<option value="${key}" ${connection.provider===key?'selected':''}>${p.label}</option>`).join('')}</select></label><label>我的 API Key <input id="custom-api-key" type="password" autocomplete="off" placeholder="粘贴后仅保存在当前浏览器会话" value="${custom?esc(connection.apiKey):''}"></label><label>服务地址 <input id="custom-base-url" inputmode="url" value="${esc(custom?connection.baseUrl:chosen.baseUrl)}" placeholder="https://api.deepseek.com"></label><label>模型名称 <input id="custom-model" value="${esc(custom?connection.model:chosen.model)}" placeholder="deepseek-flash"></label><p class="small">默认 DeepSeek Key 只保存在服务端。你自己的 Key 仅保存在当前浏览器会话，并通过后端转发。</p><p id="connection-error" class="error" hidden></p><div class="connection-actions"><button class="secondary" id="restore-default">恢复产品默认</button><button class="secondary" id="disable-default">停用产品默认</button><button class="primary" id="test-custom">测试并使用</button></div></div>`);on('restore-default',()=>{connection={mode:'default',provider:defaultConnection.provider,apiKey:'',baseUrl:defaultConnection.baseUrl,model:defaultConnection.model};saveConnection();$('#modal').close();updateConnectionButton();toast('已恢复产品默认配置');});on('disable-default',()=>{connection={mode:'disabled',provider:'deepseek',apiKey:'',baseUrl:providers.deepseek.baseUrl,model:providers.deepseek.model};saveConnection();$('#modal').close();updateConnectionButton();toast('已停用产品默认 Key');});on('custom-provider',()=>{const p=providers[$('#custom-provider').value];if(p?.baseUrl){$('#custom-base-url').value=p.baseUrl;$('#custom-model').value=p.model;}});on('test-custom',async()=>{const apiKey=$('#custom-api-key')?.value.trim(),baseUrl=$('#custom-base-url')?.value.trim()||'',model=$('#custom-model')?.value.trim()||'',error=$('#connection-error'),button=$('#test-custom');if(!apiKey){error.textContent='请先填写 API Key。';error.hidden=false;return;}if(!/^https:\/\//i.test(baseUrl)){error.textContent='服务地址需要以 https:// 开头。';error.hidden=false;return;}button.disabled=true;button.textContent='测试中…';error.hidden=true;try{const provider=$('#custom-provider').value;const b=await (await fetch('/api/ai',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'connect',clientConfig:{useDefault:false,provider,apiKey,baseUrl,model}})})).json();if(!b?.data?.ok)throw new Error(b.error||'连接未通过');connection={mode:'custom',provider,apiKey,baseUrl,model};saveConnection();connectionStatus={configured:true,provider:providers[provider]?.label||new URL(baseUrl).hostname,model};$('#modal').close();updateConnectionButton();toast('已切换为本次会话的 Key');}catch(e){error.textContent=e.message||'连接未通过，请检查 Key 和模型名称。';error.hidden=false;}finally{button.disabled=false;button.textContent='测试并使用';}});}
let toastTimer;
const toast = t => {$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600);};
let pageAnimation;
function revealContent(element=$('#app')){
 if(!element||window.matchMedia('(prefers-reduced-motion: reduce)').matches||!element.animate)return;
 if(element===$('#app'))pageAnimation?.cancel();
 const animation=element.animate([{opacity:.25,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'cubic-bezier(.2,.7,.2,1)'});
 if(element===$('#app'))pageAnimation=animation;
}
function go(step){state.step=step;render();window.scrollTo({top:0,behavior:'instant'});$('#app').focus({preventScroll:true});revealContent();}
function mobileProgress(){return `<div class="mobile-progress" aria-label="第 ${state.step+1} 步，共 6 步">${labels.map((_,i)=>`<span class="${i<=state.step?'filled':''}"></span>`).join('')} ${state.step+1} / 6</div>`;}
